// FORM TEMPLATES (Run 7, part 3): thirty neutral, general-purpose forms — one link, many people. Each is the same HTML + text tags as the document starters (helpers.mjs, legal.mjs),
// so a form is filled, signed, sealed and stored exactly like any document. Pure: imports only the two helper files.
// ★ Rules every form here keeps (and test/r7_form_templates.test.mjs checks):
//   · one person fills it in (the first role); a second role exists ONLY when the form's default is a staff counter-sign, and it holds only the decision, a note and a signature;
//   · no card numbers, bank account numbers, government ID numbers, tax forms, background-check authorizations or medical records — those need legal specifics or the payment field;
//   · every field has a type, says whether it is required, and carries help text (tooltip) where a person could hesitate;
//   · consent and acknowledgement wording sits next to the box it belongs to (checkText), never hidden in a label;
//   · `publish` is the form's default Publish options (src/documents/forms.mjs cleanFormSettings).
// Three items on the maintainer's list overlap an existing document template and form play (photo and video release, activity waiver, equipment checkout and return); they were replaced by
// appointment request, room or facility booking request, and suggestions and ideas (Run 7 log).
import { sig, signedOn } from "./helpers.mjs";
import { doc, titleBlock, p } from "./legal.mjs";

// ── a form is rows, not clauses ─────────────────────────────────────────────────────────────────────────────────
const clean = (s) => String(s).replace(/[;{}=]/g, "").replace(/"/g, "”");
const tag = (type, role, name, label, o = {}) => `{{${clean(name)};type=${type};role=${clean(role)};label=${clean(label ?? name)}${o.help ? `;tooltip="${clean(o.help)}"` : ""}${o.ph ? `;placeholder="${clean(o.ph)}"` : ""}${o.max ? `;max_length=${o.max}` : ""}${o.options ? `;options=${o.options.map(clean).join(",")}` : ""}${o.big ? ";width=420;height=54" : ""}${o.required === false ? ";required=false" : ""}}}`;
const F = {
  text: (r, n, l, o) => tag("text", r, n, l, o), area: (r, n, l, o) => tag("text", r, n, l, { max: 2000, ...o, big: true }), date: (r, n, l, o) => tag("date", r, n, l, o),
  email: (r, n, l, o) => tag("email", r, n, l, o), phone: (r, n, l, o) => tag("phone", r, n, l, o), number: (r, n, l, o) => tag("number", r, n, l, o), zip: (r, n, l, o) => tag("zip", r, n, l, o),
  check: (r, n, l, o) => tag("checkbox", r, n, l, o), pick: (r, n, l, options, o) => tag("dropdown", r, n, l, { ...o, options }), many: (r, n, l, options, o) => tag("multiselect", r, n, l, { ...o, options }),
  file: (r, n, l, o) => tag("file", r, n, l, { help: "A PDF or a picture (PNG or JPEG). It is kept exactly as you upload it.", ...o }),
};
const opt = (o = {}) => ({ ...o, required: false });
/** A labeled row: the caption a person reads, then the box. */
const row = (label, box, note = "") => `<p class="fr"><span class="fl">${label}</span> ${box}${note ? `<br><span class="fh">${note}</span>` : ""}</p>`;
/** A box with its sentence printed beside it (consent and acknowledgements). */
const agree = (role, name, sentence, o) => `<p class="fr">${F.check(role, name, sentence, o)}&nbsp; ${sentence}</p>`;
const part = (heading, ...rows) => `<h2>${heading}</h2>${rows.join("")}`;
const close = (role, sentence) => `<div class="keep"><h2>Signature</h2><p>${sentence}</p><p style="margin-top:12pt">${sig(role)}</p><p class="lbl">Signature</p><p>${signedOn(role)}</p><p class="lbl">Date</p></div>`;
/** The staff counter-sign block: a decision, a note and a signature — nothing else is filled by staff. */
const counter = (role, decision = ["Approved", "Approved with changes", "Not approved"]) => `<div class="keep"><h2>For ${role.toLowerCase()} use</h2>${row("Decision", F.pick(role, `${role} decision`, "Decision", decision))}${row("Note to the person", F.area(role, `${role} note`, "Note", opt({ help: "Optional. Shown on the signed copy." })))}<p style="margin-top:12pt">${sig(role)}</p><p class="lbl">${role} signature</p><p>${signedOn(role)}</p><p class="lbl">Date</p></div>`;
const you = (r, { phone = true, address = false } = {}) => part("About you",
  row("Full name", F.text(r, "Full name", "Full name", { max: 120 })),
  row("Email", F.email(r, "Email", "Email")),
  ...(phone ? [row("Phone", F.phone(r, "Phone", "Phone", opt({ help: "Optional. Used only to reach you about this form." })))] : []),
  ...(address ? [row("Street address", F.text(r, "Street address", "Street address", { max: 200 })), row("City", F.text(r, "City", "City", { max: 80 })), row("State or region", F.text(r, "State or region", "State or region", { max: 80 })), row("ZIP or postal code", F.zip(r, "Postal code", "ZIP or postal code"))] : []));
const PRIVACY = (r) => agree(r, "Privacy", "I understand that what I enter here is stored by the organization that published this form and used only for the purpose described above.");
const TRUE = (r) => agree(r, "Accurate", "The information I have given is true and complete to the best of my knowledge.");
const YN = ["Yes", "No"];

const form = (o) => Object.freeze({ kind: "form", paper: "letter", language: "en", ...o, html: doc(titleBlock(o.heading ?? o.title, o.sub ?? ""), p(o.intro), ...o.body) });

